ah_to.script:
var userGr = fd_data.subflow_inputs.to;
var emailList = [];
if (fd_data.subflow_inputs.to_email_address)
    emailList.push(fd_data.subflow_inputs.to_email_address);
if (userGr) {
        if (typeof userGr === "string") {
        var gr = new GlideRecord('sys_user');
        gr.addQuery('sys_id', 'IN', userGr);
        gr.query();
        while (gr.next()) {
            emailList.push(gr.getValue('email'));
        }
    }
    while (userGr.next()) 
        emailList.push(userGr.getValue('email'));
}
return emailList.join(',');

